    local constantMetatable = {
        __index = function(operands, pc)
            local indices = rawget(operands, 0)
            local index = indices[pc]
            local value = constants[index]

            if value == nil then
                error('Invalid constant index: ' .. tostring(index), 2)
            end

            rawset(operands, pc, value)

            indices[pc] = nil

            return value
        end,
    }

